package com.bainbridgetrails.map

/**
 * A map style: a MapLibre style JSON template in Compose resources.
 *
 * Templates are generated by scripts/build-map-styles.py and reference bundled tile sets with
 * placeholders (see [MapAssets.tileSets]), e.g. `"url": "{{trails}}"`; [TrailMap] substitutes local
 * `pmtiles://file://` URLs at runtime. Rationale and palettes: docs/spikes/map-render/styles.md.
 */
enum class MapStyle(val assetPath: String, val label: String, val isDark: Boolean) {
    TOPO("files/styles/topo.json", "Topo", isDark = false),
    MINIMAL_LIGHT("files/styles/minimal-light.json", "Light", isDark = false),
    DARK("files/styles/dark.json", "Dark", isDark = true),
    ;

    companion object {
        val Default = TOPO
    }
}
